// Prepare source and destination buffers and a length that meets API constraints.
// Use two distinct buffers to guarantee non-overlap.
std::string src_buf = FUZZ_PARAM_STR();
std::string dst_buf = FUZZ_PARAM_STR();

// Clamp sizes to keep runtime fast and within limits, and ensure size fits both buffers
size_t max_len = 1536u; // < 2048 as per guidance
size_t avail = src_buf.size() < dst_buf.size() ? src_buf.size() : dst_buf.size();
size_t sz = avail < max_len ? avail : max_len;

// Randomly exercise the dst == NULL early-return path about half the time
bool make_dst_null = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;

// Keep a snapshot of dst content to check that NULL dst does not modify anything (property: no copy occurs)
std::string dst_snapshot = dst_buf;

void* dst_ptr = make_dst_null ? (void*)NULL : (void*)dst_buf.data();
const void* src_ptr = (const void*)src_buf.data();

// Enforce: size must be representable as isize and non-negative
isize size = (isize)sz; // from bounded size_t, non-negative by construction

void* ret = c_safe_memcpy(dst_ptr, src_ptr, size);

if (make_dst_null) {
    // If dst is NULL, function must return NULL
    FUZZ_ASSERT(ret == NULL, "c_safe_memcpy: expected NULL return when dst is NULL");
    // Also verify destination buffer was not modified
    FUZZ_ASSERT(dst_buf == dst_snapshot, "c_safe_memcpy: dst content changed despite NULL dst");
} else {
    // When dst is non-NULL, assert bytes were copied correctly
    if (size > 0) {
        int cmp = std::memcmp(dst_buf.data(), src_buf.data(), (size_t)size);
        FUZZ_ASSERT(cmp == 0, "c_safe_memcpy: copied bytes differ from source");
    }
    // Return value should be dst
    FUZZ_ASSERT(ret == (void*)dst_buf.data(), "c_safe_memcpy: return value must equal dst");
}

// Validation summary: Ensures non-overlap via distinct buffers, non-negative size, and verifies
// correct return value and data copy behavior; also asserts no-op behavior when dst == NULL.

// Generate a readable buffer and choose a non-negative length within it
std::string buf = FUZZ_PARAM_STR();
size_t max_len = 1536u; // performance bound
size_t len_cap = buf.size() < max_len ? buf.size() : max_len;
size_t choose = *FUZZ_PARAM(unsigned int);
size_t len = (len_cap == 0) ? 0u : (choose % (len_cap + 1));

const void* key = (const void*)buf.data();
isize n = (isize)len; // non-negative by construction

// Call the hash function; no assertions beyond contract since function does no validation
volatile size_t h = c_basehash_n(key, n);
(void)h;

// Validation summary: Provides a readable buffer with non-negative length within bounds; no undefined inputs.

// Generate buffer and select length to exercise 0, 4, 8, and arbitrary paths
std::string buf = FUZZ_PARAM_STR();
size_t max_len = 1536u;
size_t len_cap = buf.size() < max_len ? buf.size() : max_len;
unsigned mode = (*FUZZ_PARAM(unsigned int)) % 4u;
size_t len = 0u;
if (mode == 0) {
    len = 0u; // empty
} else if (mode == 1) {
    len = 4u;
} else if (mode == 2) {
    len = 8u;
} else {
    len = (len_cap == 0) ? 0u : ((*FUZZ_PARAM(unsigned int)) % (len_cap + 1));
}
// Ensure len doesn't exceed available data
if (len > len_cap) len = len_cap;

const void* key = (const void*)buf.data();
isize n = (isize)len; // non-negative

volatile size_t h = c_hash_n(key, n);
(void)h;

// Validation summary: Supplies a readable buffer and non-negative length; intentionally targets 0/4/8-byte special cases.

// Generate a string; c_str() ensures NUL-termination (embedded NULs are allowed and terminate early)
std::string s = FUZZ_PARAM_STR();
const char* z = s.c_str();

volatile size_t h = c_hash_str(z);
(void)h;

// Validation summary: Provides a valid NUL-terminated string pointer as required.

// Generate a range of signed inputs including negative, zero, and positive values
int64 raw = *FUZZ_PARAM(int64);
// Create edge-biased cases sometimes: exact powers of two, -k, 0, large
unsigned mode = (*FUZZ_PARAM(unsigned int)) % 5u;
isize n;
if (mode == 0) {
    // exact power of two in a modest range
    unsigned p = (*FUZZ_PARAM(unsigned int)) % 30u; // 2^0..2^29
    n = (isize)(1ll << p);
} else if (mode == 1) {
    n = 0;
} else if (mode == 2) {
    // small negative
    n = (isize)(-(isize)((*FUZZ_PARAM(unsigned int)) % 1000u));
} else if (mode == 3) {
    // small positive non-power-of-two
    n = (isize)((*FUZZ_PARAM(unsigned int)) % 100000u + 3u);
} else {
    // use raw (clamped) to avoid extreme overflow concerns
    if (raw > (int64)2000000000) raw = 2000000000;
    if (raw < (int64)-2000000000) raw = -2000000000;
    n = (isize)raw;
}

isize r = c_next_pow2(n);

// Properties from the contract:
if (n <= 0) {
    FUZZ_ASSERT(r == 0, "c_next_pow2: n<=0 must yield 0");
} else {
    // Result should be a power of two and >= n
    FUZZ_ASSERT((r & (r - 1)) == 0, "c_next_pow2: result must be power of two");
    FUZZ_ASSERT(r >= n, "c_next_pow2: result must be >= n");
    // If n itself is a power of two, result should equal n
    if ((n & (n - 1)) == 0) {
        FUZZ_ASSERT(r == n, "c_next_pow2: exact power-of-two input should be unchanged");
    }
}

// Validation summary: Exercises negative/zero/positive cases and asserts documented properties including power-of-two and monotonicity.

// Generate haystack and needle buffers
std::string hay = FUZZ_PARAM_STR();
std::string ned = FUZZ_PARAM_STR();

// Clamp lengths for performance
size_t max_len = 1536u;
size_t slen_cap = hay.size() < max_len ? hay.size() : max_len;
size_t nlen_cap = ned.size() < max_len ? ned.size() : max_len;

// Randomize nlen, sometimes zero to hit the fast-path
unsigned r = *FUZZ_PARAM(unsigned int);
size_t nlen = (r & 3u) == 0u ? 0u : (nlen_cap == 0 ? 0u : (r % (nlen_cap + 1)));
size_t slen = (slen_cap == 0) ? 0u : ((*FUZZ_PARAM(unsigned int)) % (slen_cap + 1));

const char* str = hay.data();
const char* needle = ned.data();

char* out = c_strnstrn(str, (isize)slen, needle, (isize)nlen);

// Properties:
if (nlen == 0) {
    // For empty needle, the function should return str unconditionally
    FUZZ_ASSERT(out == (char*)str, "c_strnstrn: nlen==0 must return str");
} else if (out) {
    // If found, out must point within [str, str + slen - nlen]
    FUZZ_ASSERT(out >= str && out <= str + (ptrdiff_t)(slen >= nlen ? slen - nlen : 0u), "c_strnstrn: match pointer out of bounds");
    // And the bytes at out must equal needle[0..nlen)
    int cmp = std::memcmp(out, needle, nlen);
    FUZZ_ASSERT(cmp == 0, "c_strnstrn: returned pointer does not match needle bytes");
}

// Validation summary: Ensures non-negative bounded lengths; asserts empty-needle behavior and validates found matches lie within bounds and equal needle.

// Prepare an array h[0..15] with pseudo-random but valid size_t values derived from a fuzz buffer
std::string buf = FUZZ_PARAM_STR();
size_t cap = buf.size();

size_t h[16];
unsigned seed = *FUZZ_PARAM(unsigned int);
for (int i = 0; i < 16; ++i) {
    // Derive a slice within buf to hash into a size_t value; handle empty buffer by using len=0
    size_t off = cap ? ((size_t)(i*131u + seed) % cap) : 0u;
    size_t maxlen = cap ? (cap - off) : 0u;
    size_t len = maxlen ? ((size_t)((seed >> (i & 7)) & 63u) % (maxlen + 1u)) : 0u;
    h[i] = c_basehash_n(cap ? (const void*)(buf.data() + off) : (const void*)buf.data(), (isize)len);
}

// Choose n in [1, 16] to satisfy the precondition: h must have at least n elements
isize n = (isize)((*FUZZ_PARAM(unsigned int)) % 16u + 1u);

size_t ret = c_hash_mix_n(h, n);

// Property: function returns h[0] after in-place mixing
FUZZ_ASSERT(ret == h[0], "c_hash_mix_n: return value must equal h[0] after mixing");

// Validation summary: Ensures n>=1 and backing array has at least n elements; asserts return equals mutated h[0].

// Build a csview from a null-terminated C string
std::string s = FUZZ_PARAM_STR();
const char* c = s.c_str();
csview sv = csview_from(c);
(void)sv;

// Build a csview from a buffer and explicit length
std::string s = FUZZ_PARAM_STR();
uint64_t nraw = *FUZZ_PARAM(uint64);
isize n = s.empty() ? 0 : (isize)(nraw % (uint64_t)(s.size() + 1));
csview sv = csview_from_n(s.data(), n);
(void)sv;

// Clear a csview to empty
std::string s = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
csview_clear(&sv);
// Validate it is empty after clear
FUZZ_ASSERT(csview_is_empty(sv), "csview_clear must yield empty view");

// Query size in bytes
std::string s = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
isize n = csview_size(sv);
(void)n;

// Check emptiness
std::string s = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
bool e = csview_is_empty(sv);
(void)e;

// Compare two views for byte-wise equality
std::string a = FUZZ_PARAM_STR();
