std::string t = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
bool eq = csview_equals(sv, t.c_str());
(void)eq;

// Hash a view's bytes; ensure deterministic for same input
std::string s = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
size_t h1 = csview_hash(&sv);
size_t h2 = csview_hash(&sv);
FUZZ_ASSERT(h1 == h2, "Hash must be deterministic for same view");

// Find a subview within a view
