std::string ned = FUZZ_PARAM_STR();
csview sv = csview_from_n(hay.data(), (isize)hay.size());
csview search = csview_from_n(ned.data(), (isize)ned.size());
isize pos = csview_find_sv(sv, search);
(void)pos;

// Find a C-string within a view
std::string hay = FUZZ_PARAM_STR();
std::string ned = FUZZ_PARAM_STR();
csview sv = csview_from_n(hay.data(), (isize)hay.size());
isize pos = csview_find(sv, ned.c_str());
(void)pos;

// Check containment of a C-string within a view
std::string hay = FUZZ_PARAM_STR();
std::string ned = FUZZ_PARAM_STR();
csview sv = csview_from_n(hay.data(), (isize)hay.size());
bool has = csview_contains(sv, ned.c_str());
(void)has;

// Check prefix against a C-string
std::string s = FUZZ_PARAM_STR();
std::string pre = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
bool ok = csview_starts_with(sv, pre.c_str());
(void)ok;

// Check suffix against a C-string
std::string s = FUZZ_PARAM_STR();
std::string suf = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
bool ok = csview_ends_with(sv, suf.c_str());
(void)ok;

// Create a bounded subview at byte offsets; enforce asserted constraints
std::string s = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
// pos in [0, sv.size]
uint64_t r1 = *FUZZ_PARAM(uint64);
uint64_t r2 = *FUZZ_PARAM(uint64);
isize pos = sv.size == 0 ? 0 : (isize)(r1 % (uint64_t)(sv.size + 1));
// len >= 0
isize len = (isize)(r2 % 2048u); // keep small and non-negative
csview sub = csview_subview(sv, pos, len);
(void)sub;

// Create a bounded slice [p1, p2) with asserted constraints
std::string s = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
// Choose p1,p2 within [0, sv.size] and enforce p1 <= p2
uint64_t r1 = *FUZZ_PARAM(uint64);
uint64_t r2 = *FUZZ_PARAM(uint64);
isize a = sv.size == 0 ? 0 : (isize)(r1 % (uint64_t)(sv.size + 1));
isize b = sv.size == 0 ? 0 : (isize)(r2 % (uint64_t)(sv.size + 1));
isize p1 = a < b ? a : b;
isize p2 = a < b ? b : a; // now p1 <= p2 and p1 <= sv.size
csview sub = csview_slice(sv, p1, p2);
(void)sub;
// Validation: p1<=p2 and p1<=sv.size are enforced by construction; function clamps p2 to sv.size.

// Trim leading ASCII whitespace from start
std::string s = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
csview trimmed = csview_trim_start(sv);
// Validation: if not empty, first byte should be > ' '
if (!csview_is_empty(trimmed)) {
    FUZZ_ASSERT((unsigned char)trimmed.buf[0] > ' ', "trim_start must remove leading ASCII whitespace");
}
(void)trimmed;

// Trim trailing ASCII whitespace from end
std::string s = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
csview trimmed = csview_trim_end(sv);
// Validation: if not empty, last byte should be > ' '
if (!csview_is_empty(trimmed)) {
    FUZZ_ASSERT((unsigned char)trimmed.buf[trimmed.size - 1] > ' ', "trim_end must remove trailing ASCII whitespace");
}
(void)trimmed;

// Trim both leading and trailing ASCII whitespace
std::string s = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
csview trimmed = csview_trim(sv);
// Validation: if not empty, both ends should be > ' '
if (!csview_is_empty(trimmed)) {
    FUZZ_ASSERT((unsigned char)trimmed.buf[0] > ' ', "trim must remove leading ASCII whitespace");
    FUZZ_ASSERT((unsigned char)trimmed.buf[trimmed.size - 1] > ' ', "trim must remove trailing ASCII whitespace");
}
(void)trimmed;

// Take the last len bytes of the view; len >= 0 for intended behavior
std::string s = FUZZ_PARAM_STR();
csview sv = csview_from_n(s.data(), (isize)s.size());
uint64_t r = *FUZZ_PARAM(uint64);
// Choose len in [0, 2*sv.size] to exercise clamping to whole view
isize len = sv.size == 0 ? 0 : (isize)(r % (uint64_t)(sv.size * 2 + 1));
csview tail = csview_tail(sv, len);
// Validate size is clamped: expected = min(len, sv.size)
isize expected = len <= sv.size ? len : sv.size;
FUZZ_ASSERT(csview_size(tail) == expected, "tail size must be min(len, sv.size)");
(void)tail;

// Three-way comparison consistent with equality
std::string a = FUZZ_PARAM_STR();
std::string b = FUZZ_PARAM_STR();
csview sva = csview_from_n(a.data(), (isize)a.size());
csview svb = csview_from_n(b.data(), (isize)b.size());
int c = csview_cmp(&sva, &svb);
bool eq = csview_equals_sv(sva, svb);
// Validation: equality implies compare==0
if (eq) { FUZZ_ASSERT(c == 0, "cmp must return 0 for equal views"); }
(void)c; (void)eq;

// Pointer-based equality consistent with value equality
std::string a = FUZZ_PARAM_STR();
std::string b = FUZZ_PARAM_STR();
csview sva = csview_from_n(a.data(), (isize)a.size());
csview svb = csview_from_n(b.data(), (isize)b.size());
bool peq = csview_eq(&sva, &svb);
bool veq = csview_equals_sv(sva, svb);
// Validation: csview_eq should match byte-wise equality semantics
FUZZ_ASSERT(peq == veq, "csview_eq must agree with csview_equals_sv");

// Case-insensitive equality: view vs null-terminated C string
