// Case-insensitive three-way comparison suitable for ordering
std::string a = FUZZ_PARAM_STR();
std::string b = FUZZ_PARAM_STR();
csview sva = csview_from_n(a.data(), (isize)a.size());
csview svb = csview_from_n(b.data(), (isize)b.size());

int c_ab = csview_icmp(&sva, &svb);
int c_ba = csview_icmp(&svb, &sva);

// Antisymmetry: sign(c_ab) == -sign(c_ba)
auto sgn = [](int x){ return (x > 0) - (x < 0); };
FUZZ_ASSERT(sgn(c_ab) == -sgn(c_ba), "csview_icmp must be antisymmetric");

// Consistency with equality: compare==0 iff case-insensitive equality holds
bool ieq = csview_iequals_sv(sva, svb);
FUZZ_ASSERT((c_ab == 0) == ieq, "csview_icmp must return 0 iff case-insensitive equal");

