// Validation: compare the sv prefix of byte-length strlen(cpre) with cpre using case-insensitive equality
size_t pre_len = std::strlen(cpre);
isize take = (isize) (pre_len <= (size_t)sv.size ? pre_len : (size_t)sv.size);
csview sv_prefix = csview_subview(sv, 0, take);
csview pre_sv = csview_from(cpre);
bool expect = false;
if ((size_t)take == pre_len) {
    // Only meaningful when prefix length does not exceed sv size
    expect = csview_iequals_sv(sv_prefix, pre_sv);
}
FUZZ_ASSERT(got == expect, "csview_istarts_with must match case-insensitive equality on prefix slice");

